import { products } from './content.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={youtube:'YouTube ანალიტიკა',overview:'მიმოხილვა',feedback:'გვირჩიე რამე',applications:'განაცხადები',castings:'კასტინგები',sponsors:'სპონსორები',emails:'ბიზნეს ფოსტა',sales:'გაყიდვები',administrators:'ადმინისტრატორები'};
const statuses={new:'ახალი',reviewed:'განხილული',archived:'არქივში'};
let summary={},current='overview',rows=[],offset=0,loading=false;
const date=v=>new Date(v).toLocaleString('ka-GE',{dateStyle:'medium',timeStyle:'short'});
const fmt=v=>Number(v||0).toLocaleString('ka-GE');
function notice(msg,error=false){const n=$('#admin-notice');n.textContent=msg;n.className=error?'error':'';n.hidden=false;}
async function api(path,method='GET',body){const r=await fetch('/api/admin/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'მოთხოვნა ვერ შესრულდა.');return d}
const btn=(label,action,cls='')=>`<button type="button" class="admin-button ${cls}" data-action="${action}">${label}</button>`;
const empty=text=>`<p class="admin-empty">${text}</p>`;
const sponsorChips=(editable=false)=>summary.sponsors?.length?`<div class="admin-sponsor-chips">${summary.sponsors.map(s=>`<div class="admin-sponsor-chip"><span>${esc(s.name)}</span>${editable?`<button type="button" data-delete-sponsor="${s.id}" aria-label="${esc(s.name)} — ამოშლა">×</button>`:''}</div>`).join('')}</div>`:'<p>სპონსორები ჯერ არ არის დამატებული.</p>';
function overview(){const ms=[['ახლა საიტზე',summary.online,'ბოლო 90 წამში აქტიური'],['უნიკალური ვიზიტორი',summary.unique,'განსხვავებული ბრაუზერები'],['ბიზნესზე დაწკაპუნება',summary.businessClicks,'ელფოსტის გახსნის ღილაკი'],['გაყიდული პროდუქტი',summary.sales,'დადასტურებული რაოდენობა'],['ახალი იდეა',summary.feedback,'„გვირჩიე რამე“'],['ახალი განაცხადი',summary.applications,'კასტინგის მონაწილეები']];return `<div class="admin-metrics">${ms.map(([label,n,sub])=>`<div class="admin-metric"><span>${label}</span><strong>${fmt(n)}</strong><small>${sub}</small></div>`).join('')}</div><section class="admin-panel"><div class="admin-panel-head"><h2>აქტიური სპონსორები · ${summary.sponsors?.length||0}</h2><a class="admin-button quiet" href="#sponsors">მართვა</a></div>${sponsorChips()}</section><section class="admin-panel"><h2>ბიზნესის ინტერესი</h2><p>${fmt(summary.businessVisitors)} უნიკალურმა ვიზიტორმა დააჭირა ბიზნესის გვერდიდან ელფოსტაზე მიწერას. ღილაკი ხსნის წერილს მიმღებით <strong>info@hungryman.ge</strong>.</p><p class="admin-note">დაწკაპუნება წერილის გაგზავნას არ ადასტურებს.</p></section><p class="admin-note">დათვლა დაიწყო ${date(summary.started)}. ადმინისტრატორის ვიზიტები გამორიცხულია. უნიკალურობა ითვლება ბრაუზერის მიხედვით; სხვა მოწყობილობა ან წაშლილი cookie ახალ ვიზიტორად ჩაითვლება. ამჟამად საიტი კერძოა.</p>`}

function youtube(data){return `<section class="admin-panel"><div class="admin-panel-head"><h2>@hungrymantv</h2><span class="admin-status">${data.connected?'დაკავშირებულია':'ჯერ არ არის დაკავშირებული'}</span></div><p>საიტზე გამოჩნდება გამომწერები, ჯამური ნახვები, ბოლო ხელმისაწვდომი 28 დღის ნახვები და ამ პერიოდის საშუალო დღიური ნახვები.</p><p class="admin-note">${data.lastSync?'ბოლო წარმატებული განახლება: '+date(data.lastSync):'ავტომატური განახლება ჯერ არ დაწყებულა. Business გვერდზე შენს მიერ მოწოდებული მონაცემებია.'}</p>${data.error?`<p class="dialog-error">${esc(data.error.message)}</p>`:''}${data.connected?`<div class="admin-row-actions">${btn('ახლავე განახლება','youtube-refresh')}${btn('კავშირის გათიშვა','youtube-disconnect','danger')}</div>`:data.configured?`<form method="post" action="/api/admin/youtube/connect" target="_top"><button type="submit" class="admin-button">Google-ით დაკავშირება</button></form><p class="admin-note">აირჩიე ანგარიში, რომელსაც Hungryman-ის YouTube არხზე წვდომა აქვს, შემდეგ — Hungryman-ის არხი. მოთხოვნილი ნებართვა მხოლოდ მონაცემების წაკითხვაა.</p>`:'<p>დაკავშირებამდე შეავსე Google-ის პარამეტრები ქვემოთ.</p>'}</section><section class="admin-panel"><h2>ავტომატური განახლება</h2><p>დაკავშირების შემდეგ საიტი მონაცემებს გახსნისას ამოწმებს და YouTube-დან მაქსიმუმ საათში ერთხელ აახლებს. გახსნილი Business გვერდი ცვლილებებს ყოველ 5 წუთში ამოწმებს.</p><p class="admin-note">YouTube ანალიტიკას დამუშავება სჭირდება, ამიტომ ნაჩვენები პერიოდი შეიძლება რამდენიმე დღით ჩამორჩებოდეს დღევანდელ თარიღს. მაჩვენებლებს პერიოდი და განახლების დრო ახლავს.</p></section>${!data.connected?`<section class="admin-panel"><h2>Google-ის კავშირის პარამეტრები</h2><ol class="youtube-steps"><li><a href="https://console.cloud.google.com/apis/library" target="_blank" rel="noopener noreferrer">Google Cloud პროექტში</a> ჩართე <strong>YouTube Data API v3</strong> და <strong>YouTube Analytics API</strong>.</li><li>Google Auth Platform-ში მოამზადე consent screen და შექმენი OAuth Client ტიპით <strong>Web application</strong>. თუ აპი Testing რეჟიმშია, შენი Google ანგარიში დაამატე Test users-ში.</li><li>Authorized redirect URIs-ში ჩასვი ქვემოთ მოცემული მისამართი.</li><li>შეინახე Client ID და Client Secret ამ ფორმაში, შემდეგ დააჭირე „Google-ით დაკავშირება“.</li></ol><label class="youtube-redirect">Authorized redirect URI<input readonly value="${esc(data.redirectUri)}" aria-label="Google redirect URI"></label><form id="youtube-config" class="admin-form"><label>OAuth Client ID<input name="clientId" required autocomplete="off" placeholder="….apps.googleusercontent.com"></label><label>OAuth Client Secret<input name="clientSecret" type="password" required minlength="8" maxlength="1000" autocomplete="new-password"></label><button type="submit" class="admin-button">პარამეტრების შენახვა</button></form><p class="admin-note">მუდმივი კავშირისთვის Google-ის აპი გადაიყვანე Production რეჟიმში და დაასრულე Google-ის მოთხოვნილი შემოწმება, თუ ამას მოგთხოვს. Testing რეჟიმის ნებართვას ვადა ეწურება.</p></section>`:''}`}

function sponsors(){return `<div class="admin-panel"><h2>სპონსორის დამატება</h2><form id="sponsor-form" class="admin-form admin-inline"><label>ბრენდის სახელი<input name="name" required maxlength="100" placeholder="სპონსორის სახელი"></label><button class="admin-button" type="submit">დამატება</button></form></div><div class="admin-panel"><h2>აქტიური სპონსორები</h2>${sponsorChips(true)}</div>`}
function administrators(data){return `<section class="admin-panel"><h2>ადმინისტრატორის დამატება</h2><form id="administrator-form" class="admin-form admin-inline"><label>ელფოსტა<input name="email" type="email" required maxlength="254" autocomplete="off" placeholder="name@example.com"></label><button type="submit" class="admin-button">წვდომის მინიჭება</button></form><p class="admin-note">დამატებული ადამიანი უნდა შევიდეს ChatGPT ანგარიშით, რომელსაც ეს ელფოსტა აქვს. მას შეეძლება შეტყობინებების, განაცხადების, კასტინგების, სპონსორებისა და გაყიდვების მართვა.</p></section><section class="admin-panel"><h2>კერძო საიტზე შესვლა</h2><p>ელფოსტის დამატება ანიჭებს ადმინისტრატორის უფლებას. რადგან საიტი კერძოა, იმავე ადამიანს საიტის <strong>Share</strong> მენიუდან ნახვის უფლებაც მიეცი. შემდეგ გაუზიარე ადმინისტრაციის ბმული.</p><p class="admin-note">ელფოსტაზე მოწვევა ამ ფორმიდან ავტომატურად არ იგზავნება.</p><a class="admin-button quiet" href="/admin/">ადმინისტრაციის გვერდი ↗</a></section><div class="admin-list"><article class="admin-row"><div class="admin-row-header"><h3>${esc(data.owner)}</h3><span class="admin-status">მფლობელი</span></div><p class="meta">ადმინისტრატორების მართვა · წვდომა მუდმივია</p></article>${data.administrators.map(a=>`<article class="admin-row"><div class="admin-row-header"><h3>${esc(a.email)}</h3><span class="admin-status">ადმინისტრატორი</span></div><p class="meta">დამატებულია ${date(a.created_at)}</p><div class="admin-row-actions"><button class="admin-button danger" data-revoke-admin="${a.id}">წვდომის გაუქმება</button></div></article>`).join('')}</div>`}
function castings(){return `<div class="admin-toolbar"><p>ატვირთე ფოტო, აღწერე გადაღება და დაამატე კითხვები. გამორთული კასტინგი მონაწილეობის გვერდზე არ ჩანს.</p>${btn('＋ კასტინგის დამატება','new-casting')}</div>${rows.length?`<div class="admin-list">${rows.map(c=>`<article class="admin-row admin-casting-row"><img src="${esc(c.cover)}" alt=""><div><div class="admin-row-header"><h3>${esc(c.title)}</h3><span class="admin-status">${c.active?'აქტიური':'გამორთული'}</span></div><p>${esc(c.description.slice(0,180))}</p><p class="meta">${c.questions.length} დამატებითი კითხვა · ${date(c.created_at)}</p><div class="admin-row-actions"><button class="admin-button quiet" data-edit-casting="${c.id}">რედაქტირება</button><button class="admin-button quiet" data-toggle-casting="${c.id}">${c.active?'გამორთვა':'ჩართვა'}</button><a href="/participate/?casting=${c.id}" target="_blank">გვერდის ნახვა ↗</a></div></div></article>`).join('')}</div>`:empty('კასტინგები ჯერ არ არის დამატებული.')}`}
function listView(type,hasMore){const labels={feedback:'გამოგზავნილი იდეები აქ გამოჩნდება.',applications:'კასტინგზე მიღებული განაცხადები აქ გამოჩნდება.',emails:'ბიზნეს წერილები ჯერ არ არის შემოტანილი.'};return `${rows.length?`<div class="admin-list">${rows.map(r=>`<article class="admin-row"><div class="admin-row-header"><div><h3>${esc(type==='applications'?r.name:type==='emails'?r.subject:r.category)}</h3><p class="meta">${esc(type==='emails'?r.sender:type==='applications'?r.casting_title:r.name||'ანონიმური')} · ${date(r.created_at||r.received_at)}</p></div><span class="admin-status ${r.status}">${statuses[r.status]}</span></div><p>${esc((type==='emails'?r.body:type==='applications'?r.email+' · '+r.phone:r.message).slice(0,240))}</p><div class="admin-row-actions"><button class="admin-button quiet" data-detail="${r.id}">სრულად ნახვა</button><select aria-label="სტატუსი" data-status="${r.id}">${Object.entries(statuses).map(([s,l])=>`<option value="${s}" ${r.status===s?'selected':''}>${l}</option>`).join('')}</select></div></article>`).join('')}</div>`:empty(labels[type])}<div class="admin-pagination">${offset?btn('← წინა','previous','quiet'):'<span></span>'}${hasMore?btn('შემდეგი →','next','quiet'):''}</div>`}
function mailIntro(){return `<section class="admin-panel admin-not-connected"><div class="admin-panel-head"><h2>info@hungryman.ge</h2>${summary.mailConfigured?btn('წერილების განახლება','sync-mail','quiet'):'<span class="admin-status">ჯერ არ არის დაკავშირებული</span>'}</div><p>${summary.mailConfigured?'ბიზნესთან დაკავშირებული წერილები მოწმდება ამ განყოფილების გახსნისას და ყოველ წუთში, სანამ გვერდი გახსნილია. ძიება ეფუძნება სპონსორობის, თანამშრომლობისა და რეკლამის საკვანძო სიტყვებს.':'ბიზნეს წერილების ავტომატურად მისაღებად საჭიროა info@hungryman.ge-ის საფოსტო ანგარიშის დაკავშირება. ამ ეტაპზე წერილები საიტზე არ შემოდის.'}</p></section>`}
function sales(){return `<div class="admin-toolbar"><p>დადასტურებული გაყიდვები. ონლაინ გადახდა ჯერ არ არის ჩართული; აქ შეგიძლია უკვე გადახდილი გაყიდვა აღრიცხო.</p>${btn('＋ გაყიდვის დამატება','new-sale')}</div><div class="admin-metrics"><div class="admin-metric"><span>გაყიდული ერთეულები</span><strong>${fmt(summary.sales)}</strong><small>გაუქმებულების გარეშე</small></div><div class="admin-metric"><span>აღრიცხული შემოსავალი</span><strong>${fmt(summary.revenue/100)} ₾</strong><small>მიღებული თანხა</small></div></div>${rows.length?rows.map(s=>`<article class="admin-row"><div class="admin-row-header"><div><h3>${esc(s.product_name)}</h3><p class="meta">${date(s.created_at)} · ხელით აღრიცხული</p></div><span class="admin-status">${s.status==='paid'?'გადახდილი':'გაუქმებული'}</span></div><p>${s.quantity} ცალი × ${fmt(s.unit_price_cents/100)} ₾ = ${fmt(s.quantity*s.unit_price_cents/100)} ₾</p>${s.status==='paid'?`<div class="admin-row-actions"><button class="admin-button danger" data-cancel-sale="${s.id}">გაყიდვის გაუქმება</button></div>`:''}</article>`).join(''):empty('გაყიდვები ჯერ არ არის აღრიცხული.')}`}
async function load(){if(loading)return;loading=true;$('#admin-notice').hidden=true;current=location.hash.slice(1);if(!names[current])current='overview';$('#admin-title').textContent=names[current];document.querySelectorAll('[data-tab]').forEach(a=>a.setAttribute('aria-current',a.dataset.tab===current?'page':'false'));$('#admin-content').innerHTML=empty('მონაცემები იტვირთება…');try{summary=await api('summary');let html;if(current==='overview')html=overview();else if(current==='sponsors')html=sponsors();else if(current==='youtube'){if(!summary.canManageAdmins)throw Error('YouTube-ის დაკავშირება მხოლოდ მფლობელს შეუძლია.');html=youtube(await api('youtube/status'))}else if(current==='administrators'){if(!summary.canManageAdmins)throw Error('ადმინისტრატორების მართვა მხოლოდ მფლობელს შეუძლია.');html=administrators(await api('administrators'))}else if(current==='castings'){rows=await api('castings');html=castings()}else if(current==='sales'){rows=await api('sales');html=sales()}else{const d=await api(current+'?offset='+offset);rows=d.rows;html=(current==='emails'?mailIntro():'')+listView(current,d.hasMore)}$('#admin-content').innerHTML=html;}catch(e){$('#admin-content').innerHTML=empty('მონაცემები ვერ ჩაიტვირთა.');notice(e.message,true)}finally{loading=false}}
function dialog(html){$('#dialog-body').innerHTML=html;$('#admin-dialog').showModal()}
function detail(id){const r=rows.find(x=>x.id===id);if(!r)return;const fields=current==='applications'?[['კასტინგი',r.casting_title],['სახელი',r.name],['ელფოსტა',r.email],['ტელეფონი',r.phone],...r.answers.map(a=>[a.label,a.value||'—'])]:current==='emails'?[['გამომგზავნი',r.sender],['თემა',r.subject],['წერილი',r.body]]:[['კატეგორია',r.category],['სახელი',r.name||'ანონიმური'],['ელფოსტა',r.email||'არ არის მითითებული'],['შეტყობინება',r.message]];dialog(`<h2>${names[current]}</h2><dl class="admin-detail">${fields.map(([l,v])=>`<div><dt>${esc(l)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`)}
const qHtml=q=>`<div class="admin-question" data-qid="${q.id||crypto.randomUUID()}"><div class="admin-question-head"><strong>კითხვა</strong><button class="remove-question" type="button">ამოშლა</button></div><label>კითხვა<input data-q="label" value="${esc(q.label||'')}" required maxlength="240"></label><div class="form-grid"><label>პასუხის ტიპი<select data-q="type">${[['text','მოკლე ტექსტი'],['textarea','ვრცელი ტექსტი'],['number','რიცხვი'],['select','ერთი პასუხის არჩევა']].map(([v,l])=>`<option value="${v}" ${q.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label><input type="checkbox" data-q="required" ${q.required?'checked':''}>სავალდებულო</label></div><label class="q-options" ${q.type!=='select'?'hidden':''}>პასუხის ვარიანტები — თითო ხაზზე ერთი<textarea data-q="options">${esc((q.options||[]).join('\n'))}</textarea></label></div>`;
function editCasting(c={}){dialog(`<h2>${c.id?'კასტინგის რედაქტირება':'ახალი კასტინგი'}</h2><form class="admin-form" id="casting-form" data-id="${c.id||''}"><label>სათაური<input name="title" required maxlength="160" value="${esc(c.title||'')}" placeholder="რა ტიპის გადაღებაა?"></label><label>გადაღების აღწერა<textarea name="description" required maxlength="5000" placeholder="ვის ვეძებთ, რა მოხდება გადაღებაზე და რა უნდა იცოდეს მონაწილემ">${esc(c.description||'')}</textarea></label><label>ფოტო<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><p class="field-note">JPG, PNG ან WebP · მაქსიმუმ 5 მბ</p><input type="hidden" name="cover" value="${esc(c.cover||'')}"><img id="cover-preview" class="admin-upload-preview" ${c.cover?`src="${esc(c.cover)}"`:'hidden'} alt="კასტინგის ფოტო"><div class="admin-panel-head"><h3>დამატებითი კითხვები</h3>${btn('＋ კითხვა','add-question','quiet')}</div><p class="field-note">სახელი, ელფოსტა და ტელეფონი ფორმაში უკვე არის. სხვა კითხვები შეგიძლია მოგვიანებით დაამატო.</p><div id="questions">${(c.questions||[]).map(qHtml).join('')}</div><label><input type="checkbox" name="active" ${c.active?'checked':''}>გამოჩნდეს მონაწილეობის გვერდზე</label><p class="dialog-error" role="alert" hidden></p><button class="admin-button" type="submit">შენახვა</button></form>`)}
function newSale(){dialog(`<h2>დადასტურებული გაყიდვა</h2><form id="sale-form" class="admin-form"><label>პროდუქტი<select name="productId">${products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><div class="form-grid"><label>რაოდენობა<input name="quantity" type="number" min="1" max="10000" step="1" value="1" required></label><label>ერთეულის გადახდილი ფასი (₾)<input name="unitPrice" type="number" min="0" max="100000" step="0.01" required></label></div><p class="field-note">აღრიცხე მხოლოდ უკვე გადახდილი გაყიდვა.</p><p class="dialog-error" role="alert" hidden></p><button class="admin-button" type="submit">გაყიდვის აღრიცხვა</button></form>`)}
async function syncMail(){try{const d=await api('mail-sync','POST',{});await load();notice(`დაემატა ${d.imported} ბიზნეს წერილი.`)}catch(e){notice(e.message,true)}}
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;try{
 if(target.classList.contains('dialog-x'))$('#admin-dialog').close();
 if(target.classList.contains('remove-question'))target.closest('.admin-question').remove();
 const action=target.dataset.action;
 if(action==='new-casting')editCasting();if(action==='new-sale')newSale();if(action==='add-question'){if(document.querySelectorAll('.admin-question').length>=20)throw Error('მაქსიმუმ 20 კითხვა.');$('#questions').insertAdjacentHTML('beforeend',qHtml({}));}
 if(action==='next'||action==='previous'){offset=Math.max(0,offset+(action==='next'?50:-50));await load()}
 if(action==='youtube-refresh'){target.disabled=true;await api('youtube/refresh','POST',{});await load();notice('მონაცემები განახლებულია. განმეორებითი განახლება ხელმისაწვდომია 5 წუთში.')}
 if(action==='youtube-disconnect'&&confirm('გავთიშოთ YouTube-ის ავტომატური განახლება?')){target.disabled=true;await api('youtube/disconnect','POST',{});await load();notice('YouTube გათიშულია. საიტზე კვლავ მოწოდებული ანალიტიკა გამოჩნდება.')}
 if(action==='sync-mail')await syncMail();
 if(target.dataset.revokeAdmin&&confirm('გავაუქმოთ ამ ადმინისტრატორის წვდომა?')){target.disabled=true;await api('administrators/'+target.dataset.revokeAdmin,'DELETE');await load();notice('ადმინისტრატორის წვდომა გაუქმებულია.')}
 if(target.dataset.detail)detail(target.dataset.detail);
 if(target.dataset.editCasting)editCasting(rows.find(x=>x.id===target.dataset.editCasting));
 if(target.dataset.toggleCasting){const c=rows.find(x=>x.id===target.dataset.toggleCasting);target.disabled=true;await api('castings/'+c.id,'PUT',{...c,active:!c.active});await load()}
 if(target.dataset.deleteSponsor&&confirm('ამოვშალოთ ეს სპონსორი აქტიური სიიდან?')){await api('sponsors/'+target.dataset.deleteSponsor,'DELETE');await load()}
 if(target.dataset.cancelSale&&confirm('გავაუქმოთ გაყიდვა? ის საერთო მაჩვენებლებს გამოაკლდება.')){await api('sales/'+target.dataset.cancelSale,'PATCH',{status:'cancelled'});await load()}
}catch(err){target.disabled=false;notice(err.message,true)}});
document.addEventListener('change',async e=>{try{
 if(e.target.dataset.status){const old=rows.find(r=>r.id===e.target.dataset.status)?.status;try{await api(current+'/'+e.target.dataset.status,'PATCH',{status:e.target.value});await load()}catch(err){e.target.value=old;throw err}}
 if(e.target.dataset.q==='type')e.target.closest('.admin-question').querySelector('.q-options').hidden=e.target.value!=='select';
}catch(err){notice(err.message,true)}});
document.addEventListener('submit',async e=>{if(!['sponsor-form','casting-form','sale-form','administrator-form','youtube-config'].includes(e.target.id))return;e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;const err=f.querySelector('.dialog-error');if(err)err.hidden=true;try{
 if(f.id==='youtube-config'){await api('youtube/config','POST',{clientId:f.elements.clientId.value.trim(),clientSecret:f.elements.clientSecret.value.trim()});f.reset();await load();notice('პარამეტრები შენახულია. ახლა დააჭირე Google-ით დაკავშირებას.')}
 if(f.id==='administrator-form'){await api('administrators','POST',{email:f.elements.email.value});await load();notice('ადმინისტრატორის უფლება შენახულია. კერძო საიტზე შესასვლელად Share მენიუდანაც მიეცი ნახვის უფლება.')}
 if(f.id==='sponsor-form'){await api('sponsors','POST',{name:f.elements.name.value});await load();notice('სპონსორი დაემატა.')}
 if(f.id==='sale-form'){await api('sales','POST',Object.fromEntries(new FormData(f)));$('#admin-dialog').close();await load();notice('გაყიდვა აღირიცხა.')}
 if(f.id==='casting-form'){
  const file=f.elements.image.files[0];let cover=f.elements.cover.value;if(file){if(file.size>5*1024*1024)throw Error('ფოტო მაქსიმუმ 5 მბ უნდა იყოს.');b.textContent='ფოტო იტვირთება…';const r=await fetch('/api/admin/upload',{method:'POST',headers:{'Content-Type':file.type},body:file}),d=await r.json();if(!r.ok)throw Error(d.error);cover=d.url;f.elements.cover.value=cover;f.elements.image.value='';$('#cover-preview').src=cover;$('#cover-preview').hidden=false}
  const questions=[...f.querySelectorAll('.admin-question')].map(q=>({id:q.dataset.qid,label:q.querySelector('[data-q=label]').value,type:q.querySelector('[data-q=type]').value,required:q.querySelector('[data-q=required]').checked,options:q.querySelector('[data-q=options]').value.split('\n').map(s=>s.trim()).filter(Boolean)}));
  await api('castings'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PUT':'POST',{title:f.elements.title.value,description:f.elements.description.value,cover,active:f.elements.active.checked,questions});$('#admin-dialog').close();await load();notice('კასტინგი შენახულია.')
 }
}catch(error){if(err){err.textContent=error.message;err.hidden=false}else notice(error.message,true)}finally{b.disabled=false;if(f.id==='casting-form')b.textContent='შენახვა'}});
window.addEventListener('hashchange',()=>{offset=0;load().then(()=>{if(current==='emails'&&summary.mailConfigured)syncMail()})});
setInterval(async()=>{if(document.hidden||loading||$('#admin-dialog').open)return;try{if(current==='overview'){summary=await api('summary');$('#admin-content').innerHTML=overview()}}catch{}},30000);
setInterval(()=>{if(!document.hidden&&!loading&&current==='emails'&&summary.mailConfigured)syncMail()},60000);
await load();if(current==='emails'&&summary.mailConfigured)await syncMail();

document.addEventListener('focusin',e=>{if(e.target.matches('.youtube-redirect input'))e.target.select()});
